303.sql:
SELECT 
    (SELECT label FROM molecule WHERE molecule_id = 'TR006') AS carcinogenic,
    (SELECT COUNT(*) FROM bond WHERE molecule_id = 'TR006' AND bond_type = ' = ') AS double_bonds;

337.sql:
SELECT `element` FROM atom WHERE `molecule_id` = 'TR002'
UNION ALL
SELECT `bond_type` FROM bond WHERE `molecule_id` = 'TR002';

419.sql:
SELECT COUNT(*) 
FROM cards 
WHERE `borderColor` = 'borderless' AND `edhrecRank` > 12000;

448.sql:
WITH c_cols AS (
    SELECT c.id, c.watermark, fd.name, fd.type
    FROM cards AS c
    INNER JOIN foreign_data AS fd ON c.uuid = fd.uuid
)
SELECT name, type FROM c_cols WHERE watermark = 'abzan';
